+  );
+}
+
+function countTaskProgress(tasks: LoadedTask[]) {
+  return tasks.reduce(
+    (counts, task) => {
+      counts.total += 1;
+      switch (task.status) {
+        case "completed":
+          counts.completed += 1;
+          break;
+        case "in_progress":
+        case "pending_review":
+        case "needs_work":
+          counts.in_progress += 1;
+          break;
+        case "blocked":
+          counts.blocked += 1;
+          break;
+        default:
+          counts.pending += 1;
+          break;
+      }
+      return counts;
+    },
+    { total: 0, completed: 0, in_progress: 0, pending: 0, blocked: 0 }
