export async function fetchTasks(params?: {
	status?: string;
	tag?: string;
	assignee?: string;
	automation?: string;
	plan?: string;
	limit?: number;
	offset?: number;
}): Promise<PaginatedResponse<TaskSummary>> {
	// AC: @gh-pages-export ac-11 - Use static data in static mode
	if (isStaticMode()) {
		return fetchTasksStatic(params);
